{
  "type": "object",
  "required": [
    "event",
    "points"
  ],
  "additionalProperties": false,
  "properties": {
    "event": {
      "type": "boolean"
    },
    "points": {
      "type": "array",
      "items": {
        "type": "object",
        "required": [
          "time",
          "city",
          "event_title"
        ],
        "properties": {
          "time": {
            "type": "string"
          },
          "city": {
            "type": [
              "string",
              "null"
            ]
          },
          "event_title": {
            "type": ["string", "null"]
          }
        }
      }
    }
  }
}

